_STRUCT8 = np.ones((3, 3), dtype=int)

def goal_distance(grid):
    # MOVE-DISTANCE heuristic: count of 8-connected 'wrong regions' vs WIN.
    # Move-aligned (one action ~ fixes one region) -> A* finds the optimal path
    # with far fewer expansions than a cell-count. Validated 2026-06-17.
    return float(ndi.label(np.asarray(grid) != WIN, structure=_STRUCT8)[1])
